#!/usr/bin/env bash
# Prefetch the Docker images for the SkyRL-v0-293 dataset, BOTH the train and
# validation splits, then fan `docker load` out to every worker node.
#
# The parquets generated by prepare/prepare_swe_gym_293.py carry one
# `sandbox_overrides.environment.image` per instance.
#
#   - train.parquet: xingyaoww/sweb.eval.x86_64.* images (293 instances)
#   - val.parquet: swebench/sweb.eval.x86_64.* legacy images (23 instances,
#
#     sqlfluff/marshmallow/pvlib/astroid/pyvista/pydicom)
# The two splits share no images, so BOTH must be prefetched.
#
# All images are pulled into a shared-FS tar cache (--image-dir), then a single
# `load_all_nodes.sh` fan-out loads every tar onto each worker node.
#
# Run from this directory (examples/mini_swe/prepare/docker_scripts/):
#   bash swe_gym_293.sh
#
# Env overrides:
#   SWE_PREFETCH_WORKERS skopeo parallelism (default 64)
#
#   SWE_GYM_293_TRAIN path to train.parquet (default ../data/swe_gym_293/train.parquet)
#   SWE_GYM_293_VAL path to val.parquet (default ../data/swe_gym_293/val.parquet)
#
#   SWE_GYM_293_IMAGE_DIR tar cache dir (default ${PSRL_WORKSPACE}/docker_images/swe_gym_293)
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PREPARE_DIR="$(dirname "$SCRIPT_DIR")"

WORKERS=${SWE_PREFETCH_WORKERS:-64}
TRAIN_PARQUET="${SWE_GYM_293_TRAIN:-${PREPARE_DIR}/../data/swe_gym_293/train.parquet}"
VAL_PARQUET="${SWE_GYM_293_VAL:-${PREPARE_DIR}/../data/swe_gym_293/val.parquet}"
IMAGE_DIR="${SWE_GYM_293_IMAGE_DIR:-${PSRL_WORKSPACE}/docker_images/swe_gym_293}"

MIRRORS="docker.1ms.run,docker.1panel.live,proxy.vvvv.ee,lispy.org,registry.cyou"

# Prefetch every unique image referenced by one PSRL parquet into $IMAGE_DIR.
# prefetch_images.sh skips images already cached as tars, so re-runs are cheap.
prefetch_split() {
    local parquet="$1"
    [ -f "$parquet" ] || {
        echo "missing parquet: $parquet — run prepare_swe_gym_293.py first" >&2
        exit 1
    }
    echo "==> Prefetching images from $parquet ..."
    bash "$SCRIPT_DIR/prefetch_images.sh" \
        --parquet "$parquet" \
        --workers "$WORKERS" \
        --image-dir "$IMAGE_DIR" \
        --method skopeo \
        --mirrors "$MIRRORS" \
        --no-direct-fallback \
        --retries 10
}

# 1. Train split (xingyaoww/* images)
prefetch_split "$TRAIN_PARQUET"

# 2. Validation split (swebench/* legacy images), same tar cache, disjoint set
prefetch_split "$VAL_PARQUET"

# 3. Fan `docker load` of every cached tar out to all worker nodes
if [ -n "${PSRL_WORKSPACE:-}" ] && [ -f "${PSRL_WORKSPACE}/hosts/16GPUs" ]; then
    echo "==> Loading all cached images onto nodes from $IMAGE_DIR ..."
    bash "$SCRIPT_DIR/load_all_nodes.sh" \
        --hosts "${PSRL_WORKSPACE}/hosts/16GPUs" \
        --image-dir "$IMAGE_DIR"
else
    echo "No hosts file found; images are cached under $IMAGE_DIR — run load_all_nodes.sh manually."
fi
